// Body map and per-muscle icons. Original artwork made for this project (docs/AUTHORSHIP.md); the shapes
// are data in ./bodymap-art.js, generated by tools/bodymap/gen.py. Colours come from app.css tokens
// (--map-body, --map-idle, --heat-1..4, --ok/--warn/--bad, --accent), so light and dark follow the theme.
//
//   import { bodyMap, setValues, muscleIcon } from '../ui/bodymap.js';
//   const map = bodyMap({ view: 'front', values: { chest: 'recovering', quads: 3 } });
//   setValues(map, { chest: 'fresh' });            // repaint later
//   muscleIcon('chest', { size: 36, state: 'ready' });
//   muscleIcon('quads', { state: 'neutral' });     // recovered: muscle only subtly emphasised
//
// values: per muscle id (src/core/muscles.js) a number 0–4 (sets ramp, class is-0..is-4) or one of
// 'recovering' | 'ready' | 'fresh' (recovery states) | 'hot' (accent highlight). Missing = idle.
import { BODY, VIEW_PATHS, ICON_CROPS, VIEWBOX } from './bodymap-art.js';
import { t } from '../i18n/index.js';

const NS = 'http://www.w3.org/2000/svg';

/** Muscle ids drawn in each view: { front: [...], back: [...] }. Together they are exactly MUSCLE_IDS. */
export const MUSCLES = Object.freeze({
  front: Object.freeze(VIEW_PATHS.front.map(([m]) => m)),
  back: Object.freeze(VIEW_PATHS.back.map(([m]) => m)),
});

const STATES = new Set(['recovering', 'ready', 'fresh', 'hot']);
/** muscleIcon states: recovery colours plus 'neutral' (recovered; no status colour, as on the map). */
const ICON_STATES = new Set(['recovering', 'ready', 'fresh', 'neutral']);
const STATE_CLASSES = ['is-0', 'is-1', 'is-2', 'is-3', 'is-4', 'is-recovering', 'is-ready', 'is-fresh', 'is-hot'];

function stateClass(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return `is-${Math.max(0, Math.min(4, Math.round(v)))}`;
  if (typeof v === 'string' && STATES.has(v)) return `is-${v}`;
  return null;
}

function path(cls, d, muscle) {
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('class', cls);
  p.setAttribute('d', d);
  if (muscle) p.setAttribute('data-muscle', muscle);
  return p;
}

function viewGroup(view, dx = 0) {
  const g = document.createElementNS(NS, 'g');
  g.setAttribute('data-view', view);
  if (dx) g.setAttribute('transform', `translate(${dx} 0)`);
  for (const d of BODY) g.appendChild(path('bm-body', d));
  for (const [m, d] of VIEW_PATHS[view]) g.appendChild(path('bm-muscle', d, m));
  return g;
}

/**
 * Paint values onto a body map (front, back or both). Unknown ids are ignored.
 * @param {SVGSVGElement} svg @param {Record<string, number|string|null|undefined>} [values]
 * @returns {SVGSVGElement}
 */
export function setValues(svg, values = {}) {
  for (const p of svg.querySelectorAll('.bm-muscle')) {
    p.classList.remove(...STATE_CLASSES);
    const id = p.getAttribute('data-muscle');
    const v = id && Object.prototype.hasOwnProperty.call(values, id) ? values[id] : undefined;
    const c = stateClass(v);
    if (c) p.classList.add(c);
  }
  return svg;
}

/**
 * @param {{view?: 'front'|'back'|'both', values?: Record<string, number|string|null>, title?: string,
 *          class?: string}} [opts]
 *   title: accessible name (default 'Body map, front' / 'Body map, back' / 'Body map, front and back').
 *   Size it with CSS (class .bm; default 100 × 220 px; viewBox 200 × 440, 400 × 440 for 'both').
 * @returns {SVGSVGElement}
 */
export function bodyMap({ view = 'front', values = {}, title, class: cls } = {}) {
  const both = view === 'both';
  const v = view === 'back' ? 'back' : 'front';
  const [x, y, w, h] = VIEWBOX;
  const svg = /** @type {SVGSVGElement} */ (document.createElementNS(NS, 'svg'));
  svg.setAttribute('viewBox', `${x} ${y} ${both ? 2 * w : w} ${h}`);
  svg.setAttribute('class', ['bm', both ? 'bm-both' : null, cls].filter(Boolean).join(' '));
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', String(title ?? t(both ? 'data.bodyMap.both' : `data.bodyMap.${v}`)));
  if (both) {
    svg.appendChild(viewGroup('front'));
    svg.appendChild(viewGroup('back', w));
  } else {
    svg.appendChild(viewGroup(v));
  }
  return setValues(svg, values);
}

/** Muscle ids that have an icon (all 12). */
export const MUSCLE_ICON_IDS = Object.freeze(Object.keys(ICON_CROPS));

/**
 * Small square icon of one muscle, cut from the body map, the muscle highlighted.
 * @param {string} muscleId
 * @param {{size?: number, state?: 'recovering'|'ready'|'neutral'|'fresh'|null, label?: string}} [opts]
 *   size: px (default 36). state: highlight colour — 'recovering' red, 'ready' amber, 'neutral' the
 *   body-map idle tone (recovered muscles: only subtly emphasised), 'fresh' green (legacy); nothing =
 *   accent. label: accessible name;
 *   without it the icon is decorative (aria-hidden), as it normally sits next to the muscle's name.
 * @returns {SVGSVGElement}
 */
export function muscleIcon(muscleId, { size = 36, state = null, label } = {}) {
  const crop = Object.prototype.hasOwnProperty.call(ICON_CROPS, muscleId) ? ICON_CROPS[muscleId] : null;
  const svg = /** @type {SVGSVGElement} */ (document.createElementNS(NS, 'svg'));
  svg.setAttribute('class', ['bm', 'bm-icon', state && ICON_STATES.has(state) ? `bm-icon-${state}` : null].filter(Boolean).join(' '));
  svg.setAttribute('width', String(size));
  svg.setAttribute('height', String(size));
  svg.style.width = `${size}px`;
  svg.style.height = `${size}px`;
  svg.setAttribute('focusable', 'false');
  if (label) { svg.setAttribute('role', 'img'); svg.setAttribute('aria-label', label); } else svg.setAttribute('aria-hidden', 'true');
  if (!crop) {
    console.error(`muscleIcon(): unknown muscle "${muscleId}"`);
    return svg;
  }
  const [x, y, s] = crop.box;
  svg.setAttribute('viewBox', `${x} ${y} ${s} ${s}`);
  for (const i of crop.body) svg.appendChild(path('bm-body', BODY[i]));
  for (const [m, d] of VIEW_PATHS[crop.view]) {
    if (crop.muscles.includes(m)) svg.appendChild(path(m === muscleId ? 'bm-muscle is-hot' : 'bm-muscle', d, m));
  }
  return svg;
}
